def assign_group(node, tree):
    """Replace a same-named interface without relying on socket identifiers.

    Blender lists output interface sockets before inputs, whereas identifiers
    follow creation order. Copying that listing into a new group changes IDs;
    plain node_tree assignment silently drops links with unmatched IDs.
    """
    graph=node.id_data
    incoming=[(link.from_socket,socket.name) for socket in node.inputs for link in socket.links]
    outgoing=[(socket.name,link.to_socket) for socket in node.outputs for link in socket.links]
    defaults={}
    for socket in node.inputs:
        if hasattr(socket,'default_value'):
            value=socket.default_value
            defaults[socket.name]=(tuple(value) if not isinstance(value,(str,bpy.types.ID))
                and hasattr(value,'__iter__') else value)
    node.node_tree=tree
    for link in tuple(graph.links):
        if link.from_node==node or link.to_node==node:graph.links.remove(link)
    for key,value in defaults.items():node.inputs[key].default_value=value
    for source,key in incoming:graph.links.new(source,node.inputs[key])
    for key,target in outgoing:graph.links.new(node.outputs[key],target)


def build(*, steps=8):
    if not isinstance(steps, int) or not 0 <= steps <= 32:
        raise ValueError('Fairing requires a fixed budget between 0 and 32 steps')
    name = 'Prochitecture Streets / Pinned local quad fairing v1 / '+str(steps)
