    average.data_type = 'FLOAT_VECTOR';average.inputs['Iterations'].default_value = 1
    g.bind(g.position(), average.inputs['Value'])
    x,y,z = g.separate(g.position());ax,ay,_ = g.separate(average.outputs['Value'])
    moved = g.node('GeometryNodeSetPosition', 'Fair only free XY; preserve all pinned coordinates')
    g.bind(start.outputs['Geometry'], moved.inputs['Geometry'])
    g.bind(1.-c.V(g,mask.outputs['Attribute']), moved.inputs['Selection'])
    g.bind(g.xyz(.5*(x+ax), .5*(y+ay), z), moved.inputs['Position'])
    g.bind(moved.outputs['Geometry'], end.inputs['Geometry'])
    mesh = end.outputs['Geometry']
    face = c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    points = [];quad = 1.
    for corner in range(4):
        loop = g.node('GeometryNodeCornersOfFace');g.bind(face, loop.inputs['Face Index'])
        loop.inputs['Sort Index'].default_value = corner
        vertex = g.node('GeometryNodeVertexOfCorner')
        g.bind(loop.outputs['Corner Index'], vertex.inputs['Corner Index'])
        points.append(c._vec(g,c._sample(g,mesh,g.position(),vertex.outputs['Vertex Index'],'FLOAT_VECTOR')))
        quad = quad*g.math('COMPARE',loop.outputs['Total'],4.)
    lengths=[];crosses=[]
    for corner in range(4):
        a = c._sub(points[(corner+1)%4],points[corner])
        b = c._sub(points[(corner+2)%4],points[(corner+1)%4])
        lengths.append(c._dot(a,a));crosses.append(c._cross(a,b))
    small=large=lengths[0];minimum=crosses[0]
    for length,cross in zip(lengths[1:],crosses[1:]):
        small=g.math('MINIMUM',small,length);large=g.math('MAXIMUM',large,length)
        minimum=g.math('MINIMUM',minimum,cross)
    ratio=g.math('SQRT',large/g.math('MAXIMUM',small,1e-20))
    # This is an additional branch-admission limit, never a relaxed final guard.
    valid=c._stat(g,mesh,quad*g.math('GREATER_THAN',minimum,1e-9)*
        (1.-g.math('GREATER_THAN',ratio,MAX_EDGE_RATIO)),domain='FACE')
    size=g.node('GeometryNodeAttributeDomainSize');size.component='MESH'
    g.bind(mesh,size.inputs['Geometry'])
    valid=valid*g.math('GREATER_THAN',size.outputs['Face Count'],0.)*c._stat(g,mesh,mask.outputs['Exists'])
    g.bind(boundary._empty(g,mesh,valid),out.inputs['Geometry'])
    g.bind(mesh,out.inputs['Inspection Geometry']);g.bind(valid,out.inputs['Valid'])
    g.bind(c._stat(g,mesh,minimum,'Min',domain='FACE'),out.inputs['Minimum Corner'])
    g.bind(c._stat(g,mesh,ratio,'Max',domain='FACE'),out.inputs['Maximum Edge Ratio'])
    return g.g


