def guarded_relocation_patch(original, *, steps=8):
    """Try both endpoint choices with unchanged full surface acceptance.

    The earlier-endpoint attempt is only selected when the later-endpoint
    candidate fails. Neither a junction ID nor coordinates choose a branch.
    Failure of both candidates preserves the complete original construction.
    """
    name='Prochitecture Streets / Checked station endpoint retry v1 / '+hashlib.sha256(
        original.name.encode()).hexdigest()[:12]+' / '+str(steps)
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    candidates=[]
    for earlier in (False,True):
        guarded=guarded_patch(original,steps=steps,station_relocation=True,relocate_earlier=earlier)
        candidates.append(next(n.node_tree for n in guarded.nodes
            if n.label=='Bounded candidate with full original patch guards'))
    g=c.Graph(name)
    for s in original.interface.items_tree:
        if s.item_type=='SOCKET':g.socket(s.name,s.socket_type,s.in_out,default=getattr(s,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');calls=[]
    for label,tree in zip(('Later station endpoint','Earlier station endpoint','Original after both rejections'),
                          (*candidates,original)):
        call=g.node('GeometryNodeGroup',label);call.node_tree=tree;calls.append(call)
        for s in original.interface.items_tree:
            if s.item_type=='SOCKET' and s.in_out=='INPUT':g.bind(inp.outputs[s.name],call.inputs[s.name])
    later,earlier,fallback=calls
    budget=g.math('GREATER_THAN',inp.outputs['Relax Iterations'],steps-.5)
    use_later=c.choose(g,budget,later.outputs['Valid'],False,'BOOLEAN')
    use_earlier=c.choose(g,budget,earlier.outputs['Valid'],False,'BOOLEAN')
    branch=c.choose(g,use_later,1,c.choose(g,use_earlier,2,0,'INT'),'INT')
    for s in original.interface.items_tree:
        if s.item_type!='SOCKET' or s.in_out!='OUTPUT':continue
        kind='BOOLEAN' if s.socket_type=='NodeSocketBool' else 'GEOMETRY'
        chosen=c.choose(g,use_later,later.outputs[s.name],
            c.choose(g,use_earlier,earlier.outputs[s.name],fallback.outputs[s.name],kind),kind)
        if s.name in ('Geometry','Inspection Geometry','Status'):
            chosen=c._store(g,chosen,'st_cq_local_fairing',g.math('GREATER_THAN',branch,.5),'BOOLEAN')
            chosen=c._store(g,chosen,'st_cq_relocation_branch',branch,'INT')
        g.bind(chosen,out.inputs[s.name])
    g.g['st_local_fairing_original']=original.name
    g.g['st_local_fairing_steps']=steps
    g.g['st_local_fairing_endpoint_retry']=True
    return g.g
